// Package config loads igame's deliberately small bootstrap configuration.
// All mutable service configuration is stored in PostgreSQL.
package config

import (
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strings"
	"unicode/utf8"
)

const (
	EnvPostgresDSN        = "POSTGRES_DSN"
	EnvBootstrapAdmin     = "BOOTSTRAP_ADMIN"
	EnvBootstrapAdminPass = "BOOTSTRAP_ADMIN_PASSWORD"
	EnvEncryptionKey      = "ENCRYPTION_KEY"
)

type Config struct {
	PostgresDSN       string
	BootstrapAdmin    string
	BootstrapPassword string
	EncryptionKey     []byte
}

func Load() (Config, error) {
	c := Config{
		PostgresDSN:       strings.TrimSpace(os.Getenv(EnvPostgresDSN)),
		BootstrapAdmin:    strings.TrimSpace(os.Getenv(EnvBootstrapAdmin)),
		BootstrapPassword: os.Getenv(EnvBootstrapAdminPass),
	}
	var missing []string
	if c.PostgresDSN == "" {
		missing = append(missing, EnvPostgresDSN)
	}
	if c.BootstrapAdmin == "" {
		missing = append(missing, EnvBootstrapAdmin)
	}
	if c.BootstrapPassword == "" {
		missing = append(missing, EnvBootstrapAdminPass)
	}
	keyText := strings.TrimSpace(os.Getenv(EnvEncryptionKey))
	if keyText == "" {
		missing = append(missing, EnvEncryptionKey)
	}
	if len(missing) != 0 {
		return Config{}, fmt.Errorf("missing required environment variables: %s", strings.Join(missing, ", "))
	}
	if utf8.RuneCountInString(c.BootstrapPassword) < 12 {
		return Config{}, fmt.Errorf("%s must be at least 12 characters", EnvBootstrapAdminPass)
	}
	key, err := ParseEncryptionKey(keyText)
	if err != nil {
		return Config{}, fmt.Errorf("%s: %w", EnvEncryptionKey, err)
	}
	c.EncryptionKey = key
	return c, nil
}

func ParseEncryptionKey(value string) ([]byte, error) {
	if strings.HasPrefix(value, "base64:") {
		b, err := base64.StdEncoding.DecodeString(strings.TrimPrefix(value, "base64:"))
		if err != nil {
			return nil, errors.New("invalid base64 value")
		}
		return validateKey(b)
	}
	if strings.HasPrefix(value, "hex:") {
		b, err := hex.DecodeString(strings.TrimPrefix(value, "hex:"))
		if err != nil {
			return nil, errors.New("invalid hex value")
		}
		return validateKey(b)
	}
	// A plain 32-byte value keeps first-time offline installation simple.
	return validateKey([]byte(value))
}

func validateKey(key []byte) ([]byte, error) {
	if len(key) != 32 {
		return nil, fmt.Errorf("must decode to exactly 32 bytes, got %d", len(key))
	}
	return append([]byte(nil), key...), nil
}
package config

import "testing"

func TestParseEncryptionKey(t *testing.T) {
	for _, in := range []string{
		"12345678901234567890123456789012",
		"hex:3132333435363738393031323334353637383930313233343536373839303132",
		"base64:MTIzNDU2Nzg5MDEyMzQ1Njc4OTAxMjM0NTY3ODkwMTI=",
	} {
		got, err := ParseEncryptionKey(in)
		if err != nil || len(got) != 32 {
			t.Fatalf("ParseEncryptionKey(%q) = %d, %v", in, len(got), err)
		}
	}
	if _, err := ParseEncryptionKey("short"); err == nil {
		t.Fatal("expected short key error")
	}
}

func TestLoadRejectsWeakBootstrapPassword(t *testing.T) {
	t.Setenv(EnvPostgresDSN, "postgres://example/igame")
	t.Setenv(EnvBootstrapAdmin, "admin")
	t.Setenv(EnvBootstrapAdminPass, "too-short")
	t.Setenv(EnvEncryptionKey, "12345678901234567890123456789012")
	if _, err := Load(); err == nil {
		t.Fatal("expected a weak bootstrap password error")
	}

	t.Setenv(EnvBootstrapAdminPass, "long-enough-12")
	if _, err := Load(); err != nil {
		t.Fatalf("expected a valid bootstrap password, got %v", err)
	}
}
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
	_ "time/tzdata"

	"github.com/hkjang/igame/internal/api"
	"github.com/hkjang/igame/internal/config"
	"github.com/hkjang/igame/internal/database"
	"github.com/hkjang/igame/internal/secretbox"
	"github.com/hkjang/igame/internal/version"
	"github.com/jackc/pgx/v5/pgxpool"
)

const healthcheckURL = "http://127.0.0.1:8080/healthz"

func main() {
	log := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))
	if len(os.Args) == 2 && os.Args[1] == "healthcheck" {
		ctx, cancel := context.WithTimeout(context.Background(), 4*time.Second)
		defer cancel()
		if err := checkHealth(ctx, healthcheckURL); err != nil {
			log.Error("healthcheck failed", "error", err)
			os.Exit(1)
		}
		return
	}
	cfg, err := config.Load()
	if err != nil {
		log.Error("configuration error", "error", err)
		os.Exit(1)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	db, err := database.Open(ctx, cfg.PostgresDSN)
	if err == nil {
		err = database.Migrate(ctx, db)
	}
	if err == nil {
		err = database.EnsureBootstrapAdmin(ctx, db, cfg.BootstrapAdmin, cfg.BootstrapPassword)
	}
	cancel()
	if err != nil {
		log.Error("startup failed", "error", err)
		if db != nil {
			db.Close()
		}
		os.Exit(1)
	}
	defer db.Close()
	box, err := secretbox.New(cfg.EncryptionKey)
	if err != nil {
		log.Error("encryption initialization failed", "error", err)
		os.Exit(1)
	}
	service := api.New(db, box, log)
	server := &http.Server{Addr: ":8080", Handler: service.Router(), ReadHeaderTimeout: 10 * time.Second, ReadTimeout: 30 * time.Second, WriteTimeout: 0, IdleTimeout: 2 * time.Minute, MaxHeaderBytes: 1 << 20}
	// Idle stream clients must not hold a graceful shutdown open for the whole
	// shutdown timeout.
	server.RegisterOnShutdown(service.Drain)
	cleanupCtx, cleanupCancel := context.WithCancel(context.Background())
	defer cleanupCancel()
	go cleanupExpired(cleanupCtx, db, log)
	go func() {
		log.Info("igame started", "address", server.Addr, "version", version.Version, "commit", version.Commit)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error("HTTP server failed", "error", err)
			os.Exit(1)
		}
	}()
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	cleanupCancel()
	shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer shutdownCancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		log.Error("graceful shutdown failed", "error", err)
	}
}

// checkHealth is used by the package-free runtime image. It deliberately runs
// before application configuration and database initialization so Docker can
// probe an already-running container without a shell or utility binary.
func checkHealth(ctx context.Context, endpoint string) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return fmt.Errorf("create health request: %w", err)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("request health endpoint: %w", err)
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4<<10))
	if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
		return fmt.Errorf("health endpoint returned %s", resp.Status)
	}
	return nil
}

// cleanupExpired keeps all background state in PostgreSQL and introduces no
// additional runtime setting.
func cleanupExpired(ctx context.Context, db *pgxpool.Pool, log *slog.Logger) {
	ticker := time.NewTicker(time.Hour)
	defer ticker.Stop()
	// Run once at startup so a restart also clears whatever expired while the
	// service was down, instead of waiting a full hour for the first tick.
	cleanupOnce(ctx, db, log)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			cleanupOnce(ctx, db, log)
		}
	}
}

func cleanupOnce(ctx context.Context, db *pgxpool.Pool, log *slog.Logger) {
	ctx, cancel := context.WithTimeout(ctx, time.Minute)
	defer cancel()
	_, sessionErr := db.Exec(ctx, `DELETE FROM auth_sessions WHERE expires_at<now()`)
	_, flowErr := db.Exec(ctx, `DELETE FROM oidc_flows WHERE expires_at<now()`)
	_, gameErr := db.Exec(ctx, `UPDATE game_sessions SET status='abandoned',ended_at=now(),duration_ms=GREATEST(0,extract(epoch FROM(now()-started_at))*1000)::bigint WHERE status='active' AND started_at<now()-interval '24 hours'`)
	if sessionErr != nil || flowErr != nil || gameErr != nil {
		log.Warn("expired state cleanup failed", "session_error", sessionErr, "flow_error", flowErr, "game_session_error", gameErr)
	}
}
